export declare const GET_PRODUCTS_PAGE = "\n  query GetProducts($first: Int!, $after: String, $query: String) {\n    products(first: $first, after: $after, query: $query) {\n      pageInfo { hasNextPage endCursor }\n      edges {\n        node {\n          id\n          title\n          handle\n          descriptionHtml\n          productType\n          options { name values }\n          variants(first: 50) {\n            edges {\n              node {\n                id\n                title\n                price\n                compareAtPrice\n                availableForSale\n                selectedOptions { name value }\n              }\n            }\n          }\n          images(first: 20) {\n            edges {\n              node {\n                id\n                url\n                altText\n                width\n                height\n              }\n            }\n          }\n          metafields(first: 20, namespace: \"conversion_optimizer\") {\n            edges { node { key value } }\n          }\n        }\n      }\n    }\n  }\n";
export declare const GET_PRODUCT_BY_ID = "\n  query GetProduct($id: ID!) {\n    product(id: $id) {\n      id\n      title\n      handle\n      descriptionHtml\n      variants(first: 100) {\n        edges { node { id title price compareAtPrice availableForSale } }\n      }\n      images(first: 30) {\n        edges { node { id url altText width height } }\n      }\n      metafields(first: 30, namespace: \"conversion_optimizer\") {\n        edges { node { key value } }\n      }\n    }\n  }\n";
